package taxonomy

import (
	"strings"
)

// System nodes generated by OpenLZ, never defined in YAML.
const (
	LZUnalloc  = "LZ-UNALLOC"
	PRJUnalloc = "PRJ-UNALLOC"
	APPUnalloc = "APP-UNALLOC"
	APPInvalid = "APP-INVALID"
	ENVUnalloc = "ENV-UNALLOC"
	ENVUnspec  = "ENV-UNSPEC"
	BUUnalloc  = "BU-UNALLOC"
	CCUnalloc  = "CC-UNALLOC"
)

// Severity represents the severity of a validation finding.
type Severity string

const (
	SeverityError   Severity = "error"
	SeverityWarning Severity = "warning"
)

// Finding represents a problem identified during taxonomy validation.
type Finding struct {
	Severity Severity `json:"severity"`
	Code     string   `json:"code"`
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	File     string   `json:"file,omitempty"`
}

// BusinessUnit represents a business unit entity in the taxonomy.
type BusinessUnit struct {
	Code string `yaml:"code"`
	Name string `yaml:"name"`
	File string `yaml:"-"`
}

// CostCenter represents a cost center entity in the taxonomy.
type CostCenter struct {
	Code         string `yaml:"code"`
	Name         string `yaml:"name"`
	BusinessUnit string `yaml:"business_unit"`
	File         string `yaml:"-"`
}

// Project represents a project entity in the taxonomy.
type Project struct {
	Code         string   `yaml:"code"`
	Name         string   `yaml:"name"`
	BusinessUnit string   `yaml:"business_unit"`
	LZs          []string `yaml:"lzs,omitempty"`
	File         string   `yaml:"-"`
}

// Environment represents an environment under an application.
type Environment struct {
	Code string `yaml:"code"`
	Name string `yaml:"name"`
}

// App represents an application entity in the taxonomy.
type App struct {
	Code         string         `yaml:"code"`
	Name         string         `yaml:"name"`
	Project      string         `yaml:"project"`
	CostCenter   string         `yaml:"cost_center"`
	Environments []*Environment `yaml:"environments,omitempty"`
	File         string         `yaml:"-"`
}

// HasEnvironment reports whether the app has an environment with the given code.
func (a *App) HasEnvironment(code string) bool {
	if a == nil {
		return false
	}
	for _, env := range a.Environments {
		if env.Code == code {
			return true
		}
	}
	return false
}

// LZDefault specifies default App and/or Environment for an LZ.
type LZDefault struct {
	App         string `yaml:"app,omitempty"`
	Environment string `yaml:"environment,omitempty"`
}

// LZ represents a Landing Zone entity in the taxonomy.
type LZ struct {
	Code              string     `yaml:"code"`
	Name              string     `yaml:"name"`
	CSP               string     `yaml:"csp"`
	Currency          string     `yaml:"currency"`
	ManagementAccount string     `yaml:"management_account"`
	Default           *LZDefault `yaml:"default,omitempty"`
	File              string     `yaml:"-"`
}

// Defaults represents global default fallback mappings.
type Defaults struct {
	App         string `yaml:"app,omitempty"`
	Environment string `yaml:"environment,omitempty"`
	File        string `yaml:"-"`
}

// OULink maps an AWS Organizational Unit to an App and/or Environment.
type OULink struct {
	OU          string `yaml:"ou"`
	App         string `yaml:"app,omitempty"`
	Environment string `yaml:"environment,omitempty"`
	File        string `yaml:"-"`
}

// AccountApp specifies an App served by an account.
type AccountApp struct {
	App string `yaml:"app"`
}

// AccountEntry maps an AWS Account to an Environment and/or Apps.
type AccountEntry struct {
	Account     string        `yaml:"account"`
	Environment string        `yaml:"environment,omitempty"`
	Apps        []*AccountApp `yaml:"apps,omitempty"`
	File        string        `yaml:"-"`
}

// CostAllocation defines global cost allocation configuration.
type CostAllocation struct {
	AppTag string `yaml:"app_tag,omitempty"`
	File   string `yaml:"-"`
}

// Taxonomy is the merged model of all taxonomy entities.
type Taxonomy struct {
	BusinessUnits  []*BusinessUnit `yaml:"business_units,omitempty"`
	CostCenters    []*CostCenter   `yaml:"cost_centers,omitempty"`
	Projects       []*Project      `yaml:"projects,omitempty"`
	Apps           []*App          `yaml:"apps,omitempty"`
	LZs            []*LZ           `yaml:"lzs,omitempty"`
	Defaults       *Defaults       `yaml:"defaults,omitempty"`
	OULinks        []*OULink       `yaml:"ou_links,omitempty"`
	Accounts       []*AccountEntry `yaml:"accounts,omitempty"`
	CostAllocation *CostAllocation `yaml:"cost_allocation,omitempty"`

	// Lookup caches
	appsByCode   map[string]*App
	appsByTag    map[string]*App
	lzsByMgmtAcc map[string]*LZ
	lzsByCode    map[string]*LZ
	prjsByCode   map[string]*Project
	busByCode    map[string]*BusinessUnit
	ccsByCode    map[string]*CostCenter
}

// AppByCode returns the App matching code, or nil if not found.
func (t *Taxonomy) AppByCode(code string) (*App, bool) {
	if t.appsByCode == nil {
		t.buildIndexes()
	}
	app, ok := t.appsByCode[code]
	return app, ok
}

// AppByTag returns the App whose code matches tag (case-insensitively, trimmed spaces per D-011).
func (t *Taxonomy) AppByTag(tag string) (*App, bool) {
	if t.appsByTag == nil {
		t.buildIndexes()
	}
	normalized := strings.ToUpper(strings.TrimSpace(tag))
	app, ok := t.appsByTag[normalized]
	return app, ok
}

// EnvironmentByAppAndCode returns the Environment matching envCode under appCode.
func (t *Taxonomy) EnvironmentByAppAndCode(appCode, envCode string) (*Environment, bool) {
	app, ok := t.AppByCode(appCode)
	if !ok || app == nil {
		return nil, false
	}
	for _, env := range app.Environments {
		if env.Code == envCode {
			return env, true
		}
	}
	return nil, false
}

// LZByManagementAccount returns the LZ whose management_account matches accountID.
func (t *Taxonomy) LZByManagementAccount(accountID string) (*LZ, bool) {
	if t.lzsByMgmtAcc == nil {
		t.buildIndexes()
	}
	lz, ok := t.lzsByMgmtAcc[accountID]
	return lz, ok
}

// LZByCode returns the LZ matching code.
func (t *Taxonomy) LZByCode(code string) (*LZ, bool) {
	if t.lzsByCode == nil {
		t.buildIndexes()
	}
	lz, ok := t.lzsByCode[code]
	return lz, ok
}

// ProjectByCode returns the Project matching code.
func (t *Taxonomy) ProjectByCode(code string) (*Project, bool) {
	if t.prjsByCode == nil {
		t.buildIndexes()
	}
	prj, ok := t.prjsByCode[code]
	return prj, ok
}

// BusinessUnitByCode returns the BusinessUnit matching code.
func (t *Taxonomy) BusinessUnitByCode(code string) (*BusinessUnit, bool) {
	if t.busByCode == nil {
		t.buildIndexes()
	}
	bu, ok := t.busByCode[code]
	return bu, ok
}

// CostCenterByCode returns the CostCenter matching code.
func (t *Taxonomy) CostCenterByCode(code string) (*CostCenter, bool) {
	if t.ccsByCode == nil {
		t.buildIndexes()
	}
	cc, ok := t.ccsByCode[code]
	return cc, ok
}

// buildIndexes populates lookup maps for fast entity resolution.
func (t *Taxonomy) buildIndexes() {
	t.appsByCode = make(map[string]*App, len(t.Apps))
	t.appsByTag = make(map[string]*App, len(t.Apps))
	for _, app := range t.Apps {
		if app != nil {
			t.appsByCode[app.Code] = app
			t.appsByTag[strings.ToUpper(strings.TrimSpace(app.Code))] = app
		}
	}

	t.lzsByMgmtAcc = make(map[string]*LZ, len(t.LZs))
	t.lzsByCode = make(map[string]*LZ, len(t.LZs))
	for _, lz := range t.LZs {
		if lz != nil {
			t.lzsByCode[lz.Code] = lz
			if lz.ManagementAccount != "" {
				t.lzsByMgmtAcc[lz.ManagementAccount] = lz
			}
		}
	}

	t.prjsByCode = make(map[string]*Project, len(t.Projects))
	for _, prj := range t.Projects {
		if prj != nil {
			t.prjsByCode[prj.Code] = prj
		}
	}

	t.busByCode = make(map[string]*BusinessUnit, len(t.BusinessUnits))
	for _, bu := range t.BusinessUnits {
		if bu != nil {
			t.busByCode[bu.Code] = bu
		}
	}

	t.ccsByCode = make(map[string]*CostCenter, len(t.CostCenters))
	for _, cc := range t.CostCenters {
		if cc != nil {
			t.ccsByCode[cc.Code] = cc
		}
	}
}
